export default function OrdersPage() {
  useEffect(() => {
    // Attach client-side interactions for buttons, tabs, dropdowns
    const handleActionClick = (e: MouseEvent) => {
      const target = (e.target as HTMLElement)?.closest("button, a");
      if (!target) return;
      const text = (target as HTMLElement).innerText?.trim();
      const href = target.getAttribute("href");
      if (href && href.startsWith("http")) return; // external link
      // If internal link without real target or action button
    };
    document.addEventListener("click", handleActionClick);
    return () => document.removeEventListener("click", handleActionClick);
  }, []);

  return (
    <div className="size-full flex-1 min-w-0">
      <div dangerouslySetInnerHTML={{ __html: PAGE_HTML }} />
    </div>
  );
}
